function quoteEntries(value: unknown): Array<{ quote: string; sourceId: string }> {
  const out: Array<{ quote: string; sourceId: string }> = [];
  const walk = (v: unknown): void => {
    if (Array.isArray(v)) {
      for (const e of v) walk(e);
      return;
    }
    if (typeof v === 'object' && v !== null) {
      const r = v as Record<string, unknown>;
      if (typeof r['quote'] === 'string') {
        const sid = typeof r['sourceId'] === 'string' ? (r['sourceId'] as string) : (typeof r['focusSourceId'] === 'string' ? (r['focusSourceId'] as string) : '');
        out.push({ quote: r['quote'] as string, sourceId: sid });
      }
      if (typeof r['focusQuote'] === 'string') {
        out.push({ quote: r['focusQuote'] as string, sourceId: typeof r['focusSourceId'] === 'string' ? (r['focusSourceId'] as string) : '' });
      }
      for (const k of Object.keys(r)) {
        if (k === 'quote' || k === 'focusQuote') continue;
        walk(r[k]);
      }
    }
  };
  walk(value);
  return out;
}

function idEntries(value: unknown): string[] {
  const out: string[] = [];
  const walk = (v: unknown): void => {
    if (Array.isArray(v)) {
      for (const e of v) walk(e);
      return;
    }
    if (typeof v === 'object' && v !== null) {
      const r = v as Record<string, unknown>;
      for (const k of ['id', 'fromId', 'toId', 'groupId', 'xVariable']) {
        if (typeof r[k] === 'string' && (k === 'id' || k === 'fromId' || k === 'toId' || k === 'groupId')) out.push(r[k] as string);
      }
      for (const k of Object.keys(r)) walk(r[k]);
    }
  };
  walk(value);
  return out;
}

